def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    coins from the list `coins`. If impossible, return -1.
    """
    # Edge cases
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Remove non-positive coin values, as they are useless or could cause infinite loops
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array where dp[i] is min coins for amount i, initialized to a large sentinel
    max_val = amount + 1  # sentinel greater than any possible number of coins
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If using coin c improves the count, update
                prev = dp[a - c] + 1
                if prev < dp[a]:
                    dp[a] = prev
    return dp[amount] if dp[amount] != max_val else -1

