def solve(path: str) -> str:
    """Simplify an absolute Unix path.
    Handles '.', '..', multiple slashes, and removes trailing slash unless root.
    If the input is empty, returns '/' as the root.
    """
    if not path:
        return '/'
    parts = path.split('/')
    stack: list[str] = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                stack.pop()
            # else stay at root
        else:
            stack.append(p)
    # Join components; root is '/' if stack empty
    return '/' + '/'.join(stack)

