            else:
                cur.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(cur))
                cur = []
            elif ch == '"':
                in_quotes = True
            else:
                cur.append(ch)
        i += 1
    fields.append(''.join(cur))
