def solve(coins, amount):
    """Return the minimum number of coins needed to make up amount.
    coins: list of positive ints (may be empty).
    amount: non-negative int.
    Return -1 if impossible.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Initialize DP array with amount+1 (as infinity)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # Use coin c
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

