    # Longest strictly increasing subsequence: patience sorting, O(n log n).
    import bisect
    tails = []
    for x in nums or []:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

